<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3';
import { Brain, Gamepad2, Pencil, Puzzle, Rocket, Trophy, Trash2, X } from '@lucide/vue';
import { ref } from 'vue';

const iconMap = { 'gamepad-2': Gamepad2, puzzle: Puzzle, trophy: Trophy, brain: Brain, rocket: Rocket };
type Game = { id: number; nama: string; deskripsi: string | null; wordwall_url: string; ikon: keyof typeof iconMap };
const props = defineProps<{ kelas: { id: number; nama: string }; games: Game[]; ikonPilihan: (keyof typeof iconMap)[] }>();
const open = ref(false);
const editingId = ref<number | null>(null);
const form = useForm({ nama: '', deskripsi: '', wordwall_url: '', ikon: 'gamepad-2' as keyof typeof iconMap });

defineOptions({ layout: { breadcrumbs: [{ title: 'Game' }] } });
function startAdd() { open.value = true; editingId.value = null; form.reset(); form.clearErrors(); }
function startEdit(game: Game) { open.value = true; editingId.value = game.id; form.defaults({ nama: game.nama, deskripsi: game.deskripsi ?? '', wordwall_url: game.wordwall_url, ikon: game.ikon }); form.reset(); }
function close() { open.value = false; editingId.value = null; form.reset(); form.clearErrors(); }
function submit() { const options = { onSuccess: close }; editingId.value ? form.put(`/kelas/${props.kelas.id}/game/${editingId.value}`, options) : form.post(`/kelas/${props.kelas.id}/game`, options); }
function remove(game: Game) { if (window.confirm(`Hapus game "${game.nama}"?`)) form.delete(`/kelas/${props.kelas.id}/game/${game.id}`); }
</script>

<template>
    <Head title="Game" />
    <div class="min-h-screen bg-amber-50/60 px-4 py-6 md:px-8 md:py-10"><div class="mx-auto max-w-6xl"><header class="flex items-center justify-between"><Link :href="`/kelas/${kelas.id}`" class="text-sm font-semibold text-amber-900 hover:underline">Kembali ke kelas</Link><span class="font-extrabold tracking-wide text-amber-900">E-LKPD WEB</span></header><div class="mt-10 flex items-end justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-[0.18em] text-amber-700">Aktivitas interaktif</p><h1 class="mt-2 text-3xl font-bold text-amber-950">Game {{ kelas.nama }}</h1><p class="mt-2 text-sm text-amber-900/70">Kelola permainan Wordwall untuk siswa.</p></div><button type="button" class="inline-flex items-center gap-2 rounded-md bg-amber-800 px-4 py-2 text-sm font-semibold text-white hover:bg-amber-900" @click="startAdd"><Gamepad2 class="size-4" /> Tambah game</button></div><div v-if="games.length" class="mt-8 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><article v-for="game in games" :key="game.id" class="flex min-h-44 aspect-[1/.9] flex-col rounded-lg border border-amber-200 bg-white p-3 shadow-sm"><div class="flex items-start justify-between"><span class="flex size-11 items-center justify-center rounded-xl border-2 border-amber-300 bg-amber-100 text-amber-800 shadow-inner"><component :is="iconMap[game.ikon] ?? Gamepad2" class="size-5" /></span><div class="flex gap-0.5"><button type="button" title="Edit game" class="rounded p-1.5 text-amber-800 hover:bg-amber-50" @click="startEdit(game)"><Pencil class="size-3.5" /></button><button type="button" title="Hapus game" class="rounded p-1.5 text-red-700 hover:bg-red-50" @click="remove(game)"><Trash2 class="size-3.5" /></button></div></div><h2 class="mt-2 truncate text-sm font-bold text-amber-950">{{ game.nama }}</h2><p class="mt-1 min-h-8 line-clamp-2 text-xs leading-snug text-amber-900/70">{{ game.deskripsi || 'Game Wordwall untuk kelas ini.' }}</p><a :href="game.wordwall_url" target="_blank" rel="noreferrer" class="mt-auto block rounded-md bg-amber-800 px-2 py-1.5 text-center text-xs font-semibold text-white hover:bg-amber-900">Buka Wordwall ↗</a></article></div><div v-else class="mt-8 rounded-xl border border-dashed border-amber-300 bg-white/70 p-12 text-center text-amber-900">Belum ada game. Tambahkan game Wordwall pertama.</div></div><div v-if="open" class="fixed inset-0 z-50 grid place-items-center bg-amber-950/50 p-4" @click.self="close"><section class="w-full max-w-lg rounded-xl bg-white p-6 shadow-2xl"><div class="flex justify-between"><div><p class="text-xs font-bold uppercase tracking-widest text-amber-700">{{ editingId ? 'Edit game' : 'Game baru' }}</p><h2 class="text-xl font-bold text-amber-950">Wordwall</h2></div><button type="button" title="Tutup" @click="close"><X class="size-5 text-amber-900" /></button></div><form class="mt-5 space-y-4" @submit.prevent="submit"><label class="grid gap-1 text-sm font-semibold text-amber-900">Nama game<input v-model="form.nama" required class="rounded-md border border-amber-300 px-3 py-2 font-normal" placeholder="Contoh: Kuis Ekosistem" /><small v-if="form.errors.nama" class="text-red-600">{{ form.errors.nama }}</small></label><label class="grid gap-1 text-sm font-semibold text-amber-900">Deskripsi<textarea v-model="form.deskripsi" rows="3" class="rounded-md border border-amber-300 px-3 py-2 font-normal" placeholder="Deskripsi singkat game"></textarea><small v-if="form.errors.deskripsi" class="text-red-600">{{ form.errors.deskripsi }}</small></label><label class="grid gap-1 text-sm font-semibold text-amber-900">Link Wordwall<input v-model="form.wordwall_url" required type="url" class="rounded-md border border-amber-300 px-3 py-2 font-normal" placeholder="https://wordwall.net/..." /><small v-if="form.errors.wordwall_url" class="text-red-600">{{ form.errors.wordwall_url }}</small></label><label class="grid gap-1 text-sm font-semibold text-amber-900">Ikon game<select v-model="form.ikon" class="rounded-md border border-amber-300 px-3 py-2 font-normal"><option v-for="ikon in ikonPilihan" :key="ikon" :value="ikon">{{ ikon }}</option></select></label><button type="submit" :disabled="form.processing" class="w-full rounded-md bg-amber-800 px-4 py-2.5 font-semibold text-white hover:bg-amber-900 disabled:opacity-60">{{ form.processing ? 'Menyimpan...' : 'Simpan game' }}</button></form></section></div></div>
</template>
